import React, { useState, useEffect, useRef, useMemo } from 'react';
import { api } from '../services/apiService';
import { User } from '../types';
import { CheckCircleIcon } from '../components/Icons';

interface AttendanceProps {
  user: User;
  onAttendanceSuccess: () => void;
  lokasiData: any[];
  currentMateri: any; 
  joinDate?: string | null;
}

interface HistoryItem {
  waktu: string;
  jenis: string;
  cabang: string;
  shift: string;
}

interface GroupedHistory {
  dateKey: string;
  dateDisplay: string;
  shortDate: string;
  monthYear: string;
  cabang: string; 
  shift: string;
  masuk?: string;
  pulang?: string;
  status?: 'TEPAT WAKTU' | 'TELAT';
}

const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const R = 6371e3; // metres
  const φ1 = lat1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const Δφ = (lat2 - lat1) * Math.PI / 180;
  const Δλ = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

// Fungsi parsing tanggal yang LEBIH KUAT
const parseDateHelper = (dateStr: any): Date | null => {
  try {
    if (!dateStr) return null;
    if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;

    // Bersihkan string
    const s = String(dateStr).trim();
    if (!s) return null;

    // 1. Coba Date.parse langsung
    const timestamp = Date.parse(s);
    if (!isNaN(timestamp)) {
      return new Date(timestamp);
    }

    // 2. Parse Manual "M/D/YYYY" atau "D/M/YYYY"
    // Ambil bagian tanggal saja (buang jam jika ada)
    const datePart = s.split(/[ ,T]+/)[0];
    const bits = datePart.split(/[\/\-\.]/);

    if (bits.length === 3) {
      let d, m, y;
      const b0 = parseInt(bits[0]);
      const b1 = parseInt(bits[1]);
      const b2 = parseInt(bits[2]);

      // Deteksi posisi tahun (4 digit)
      if (String(bits[2]).length === 4) { // Format: XX/XX/YYYY
        // Logika Deteksi:
        if (b0 > 12) { 
           d = b0; m = b1; y = b2; 
        } else if (b1 > 12) {
           m = b0; d = b1; y = b2;
        } else {
           // Asumsi Default Sheet (US Format: MM/DD/YYYY)
           m = b0; d = b1; y = b2;
        }
      } else if (String(bits[0]).length === 4) { // Format: YYYY/MM/DD
        y = b0; m = b1; d = b2; 
      } else {
        return null;
      }

      const finalDate = new Date(y, m - 1, d);
      return isNaN(finalDate.getTime()) ? null : finalDate;
    }

    return null;
  } catch (e) { return null; }
};

export const Attendance: React.FC<AttendanceProps> = ({ user, onAttendanceSuccess, lokasiData, currentMateri, joinDate }) => {
  const [activeView, setActiveView] = useState<'absen' | 'laporan'>('absen');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [jenis, setJenis] = useState('Masuk');
  const [shift, setShift] = useState('');
  const [cabang, setCabang] = useState('');
  const [photo, setPhoto] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [gps, setGps] = useState<{ lat: number, lng: number, accuracy: number } | null>(null);
  const [attendanceHistory, setAttendanceHistory] = useState<HistoryItem[]>([]);

  const [showSuccessView, setShowSuccessView] = useState(false);

  const now = new Date();
  const monthFullNames = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthYearFilter = `${monthFullNames[now.getMonth()]} ${now.getFullYear()}`;
  const [selectedMonth, setSelectedMonth] = useState<string>(currentMonthYearFilter);
  const [isSyncing, setIsSyncing] = useState(false);

  const [distance, setDistance] = useState<number | null>(null);
  const [allowedRadius, setAllowedRadius] = useState<number>(100);
  const [isInsideRadius, setIsInsideRadius] = useState<boolean | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const forceView = localStorage.getItem('force_attendance_view');
    if (forceView === 'laporan') {
      setActiveView('laporan');
      localStorage.removeItem('force_attendance_view');
    }
  }, []);

  useEffect(() => {
    const fetchHistory = async () => {
      setIsSyncing(true);
      try {
        const history = await api.getAttendanceHistory(user.email);
        if (history && Array.isArray(history)) {
          // SORTING MANUAL
          const sorted = [...history].sort((a: any, b: any) => {
            const tA = a.waktu || a.Waktu || a.timestamp || a.Timestamp || "";
            const tB = b.waktu || b.Waktu || b.timestamp || b.Timestamp || "";
            const dateA = parseDateHelper(tA);
            const dateB = parseDateHelper(tB);
            return (dateB?.getTime() || 0) - (dateA?.getTime() || 0);
          });
          setAttendanceHistory(sorted);
        }
      } catch (err) {
        console.error("Gagal ambil history:", err);
      } finally {
        setIsSyncing(false);
      }
    };
    fetchHistory();
  }, [user.email, activeView]);

  // --- SMART JOIN DATE CALCULATION ---
  const effectiveJoinDate = useMemo(() => {
    // Prioritas 1: Data dari Backend (jika ada dan valid)
    if (joinDate) {
      const parsed = parseDateHelper(joinDate);
      if (parsed) return { date: parsed, source: 'Backend' };
    }

    // Prioritas 2: Data Riwayat Terlama (Fallback Cerdas)
    if (attendanceHistory.length > 0) {
      // Sort Ascending (Terlama ke Terbaru) untuk mencari tanggal pertama kali absen
      const sortedAsc = [...attendanceHistory].sort((a: any, b: any) => {
        const tA = a.waktu || a.Waktu || a.timestamp || a.Timestamp || "";
        const tB = b.waktu || b.Waktu || b.timestamp || b.Timestamp || "";
        const dateA = parseDateHelper(tA);
        const dateB = parseDateHelper(tB);
        return (dateA?.getTime() || 0) - (dateB?.getTime() || 0);
      });

      const firstRecord = sortedAsc[0];
      const timeStr = (firstRecord as any).waktu || (firstRecord as any).Waktu;
      const parsedHistoryDate = parseDateHelper(timeStr);

      if (parsedHistoryDate) {
        // --- LOGIKA KOREKSI: MUNDURKAN 1 HARI ---
        // Karena data "Signup" tidak tersedia, kita asumsikan karyawan mendaftar
        // 1 hari sebelum absen pertama mereka.
        // Contoh: Absen pertama tgl 16 -> Estimasi Join tgl 15.
        // Ini memastikan perhitungan Max Hadir mencakup hari pendaftaran.
        const adjustedDate = new Date(parsedHistoryDate);
        adjustedDate.setDate(parsedHistoryDate.getDate() - 1);

        return { date: adjustedDate, source: 'History (Est. -1 Day)' };
      }
    }

    return null;
  }, [joinDate, attendanceHistory]);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    if (navigator.geolocation) {
      const watcher = navigator.geolocation.watchPosition(
        (pos) => setGps({ lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy }),
        (err) => console.error(err), 
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
      return () => {
        navigator.geolocation.clearWatch(watcher);
        clearInterval(timer);
      };
    }
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (gps && cabang && lokasiData.length > 0) {
      const targetCabang = lokasiData.find(l => {
        const nameInSheet = String(l?.namacabang || l?.nama || l?.Nama || "").toUpperCase();
        return nameInSheet === cabang.toUpperCase();
      });

      if (targetCabang) {
        const latTarget = parseFloat(targetCabang.latitude || targetCabang.lat);
        const lngTarget = parseFloat(targetCabang.longitude || targetCabang.lng);
        const radiusTarget = parseFloat(targetCabang.radiusmeter || targetCabang.radius || 100);
        if (!isNaN(latTarget) && !isNaN(lngTarget)) {
          const dist = calculateDistance(gps.lat, gps.lng, latTarget, lngTarget);
          setDistance(dist);
          setAllowedRadius(radiusTarget);
          setIsInsideRadius(dist <= radiusTarget);
        } else {
          setDistance(null);
          setIsInsideRadius(true);
        }
      }
    }
  }, [gps, cabang, lokasiData]);

  const lastTodayRecord = [...attendanceHistory].find(h => {
    const timeStr = (h as any).waktu || (h as any).Waktu || (h as any).timestamp || (h as any).Timestamp;
    const date = parseDateHelper(timeStr);
    return date && date.toDateString() === new Date().toDateString();
  });

  const isCurrentlyCheckedIn = lastTodayRecord?.jenis === 'Masuk';

  useEffect(() => {
    if (isCurrentlyCheckedIn) {
      setJenis('Pulang');
      setShift(lastTodayRecord?.shift || '');
      if (!cabang) setCabang(lastTodayRecord?.cabang || '');
    } else {
      setJenis('Masuk');
      setShift('');
    }
  }, [isCurrentlyCheckedIn, lastTodayRecord]);

  const handleAbsen = async () => {
    if (!photo || !shift || !cabang || !gps) return alert("Lengkapi data.");
    if (isInsideRadius === false) {
      alert(`ABSENSI DITOLAK: Anda berada di luar radius lokasi salon.`);
      return;
    }

    setLoading(true);
    try {
      const materiToSend = currentMateri?.bab || currentMateri?.judul || "Materi Umum";
      const distVal = Math.round(distance || 0);
      const statusLokasiFix = `${distVal} Meter`;

      const result = await api.absen({
        nama: user.nama, email: user.email, jenis, shift, cabang,
        lat: gps.lat, lng: gps.lng, accuracy: gps.accuracy,
        jarak: distVal,
        foto: photo, 
        statusLokasi: statusLokasiFix, 
        materi: materiToSend
      });

      if (result.status === 'sukses') {
        setShowSuccessView(true);
      } else {
        alert(result.message || "Gagal absen.");
      }
    } catch (e) {
      alert("Kesalahan koneksi.");
    } finally {
      setLoading(false);
    }
  };

  const startCamera = async () => {
    if (isCameraOpen || photo) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      streamRef.current = stream;
      setIsCameraOpen(true);
      setTimeout(() => { if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play(); } }, 100);
    } catch (e) { alert("Akses kamera ditolak."); }
  };

  const takePhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (videoRef.current && canvasRef.current) {
      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth; canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        setPhoto(canvas.toDataURL('image/jpeg', 0.8));
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setIsCameraOpen(false);
      }
    }
  };

  const resetPhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPhoto(null);
    setIsCameraOpen(false);
    startCamera();
  };

  const getLogs = (): GroupedHistory[] => {
    const groups: Record<string, GroupedHistory> = {};
    const monthNames = ["JAN", "FEB", "MAR", "APR", "MEI", "JUN", "JUL", "AGT", "SEP", "OKT", "NOV", "DES"];

    attendanceHistory.forEach(item => {
      const timeStr = (item as any).waktu || (item as any).Waktu || (item as any).timestamp || (item as any).Timestamp;
      const date = parseDateHelper(timeStr);
      if (!date) return;
      const dStr = date.getDate().toString().padStart(2, '0');
      const mStr = (date.getMonth() + 1).toString().padStart(2, '0');
      const y = date.getFullYear();
      const mIdx = date.getMonth();
      const key = `${y}${mStr}${dStr}`; 

      if (!groups[key]) {
        groups[key] = {
          dateKey: key, 
          dateDisplay: `${dStr}/${mStr}/${y}`,
          shortDate: `${dStr} ${monthNames[mIdx]}`,
          monthYear: `${monthFullNames[mIdx]} ${y}`,
          cabang: item.cabang, shift: item.shift
        };
      }

      const timeHM = date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }).replace('.', ':');

      if (item.jenis === 'Masuk' && !groups[key].masuk) {
        groups[key].masuk = timeHM;
        const [h, min] = timeHM.split(':').map(Number);
        if (item.shift === 'Pagi' || item.shift === 'Full Day') {
           groups[key].status = (h > 8 || (h === 8 && min > 35)) ? 'TELAT' : 'TEPAT WAKTU';
        } else if (item.shift === 'Siang') {
           groups[key].status = (h > 12 || (h === 12 && min > 35)) ? 'TELAT' : 'TEPAT WAKTU';
        } else {
           groups[key].status = 'TEPAT WAKTU';
        }
      } else if (item.jenis === 'Pulang' && !groups[key].pulang) {
        groups[key].pulang = timeHM;
      }
    });

    const all = Object.values(groups) as GroupedHistory[];
    all.sort((a, b) => b.dateKey.localeCompare(a.dateKey));
    return selectedMonth ? all.filter(d => d.monthYear === selectedMonth) : all;
  };

  const logs = getLogs();

  // STATISTIK PERHITUNGAN
  const totalHadirUnique = logs.length; 
  const totalTepat = logs.filter(l => l.status === 'TEPAT WAKTU').length;
  const totalTelat = logs.filter(l => l.status === 'TELAT').length;

  // --- LOGIKA HITUNG HARI & LIBUR ---
  let totalLibur = 0; 
  let maxHadir = 0; 
  let allowedOffs = 0;

  if (selectedMonth) {
    const parts = selectedMonth.split(' ');
    const mIdx = monthFullNames.findIndex(m => m.toLowerCase() === parts[0].toLowerCase());
    const mYear = parseInt(parts[1]);

    if (mIdx !== -1 && !isNaN(mYear)) {
      const daysInMonth = new Date(mYear, mIdx + 1, 0).getDate();

      // 1. Tentukan Tanggal Mulai (Start Day)
      let startDay = 1;

      if (effectiveJoinDate) {
         const jYear = effectiveJoinDate.date.getFullYear();
         const jMonth = effectiveJoinDate.date.getMonth();

         // Jika Join pada bulan & tahun yang sama dengan filter
         if (jYear === mYear && jMonth === mIdx) {
            startDay = effectiveJoinDate.date.getDate();
         } 
         // Jika Join di Masa Depan dari filter ini
         else if (jYear > mYear || (jYear === mYear && jMonth > mIdx)) {
            startDay = 999; // Belum mulai
         }
         // Jika Join di masa lalu, startDay tetap 1 (Full Month)
      }

      // 2. Tentukan Tanggal Akhir Efektif (Untuk menghitung Libur Berjalan)
      const nowReal = new Date();
      let effectiveEndDay = daysInMonth; 

      if (nowReal.getFullYear() === mYear && nowReal.getMonth() === mIdx) {
         effectiveEndDay = nowReal.getDate();
      }
      else if (new Date(mYear, mIdx, 1) > nowReal) {
         effectiveEndDay = 0;
         startDay = 999;
      }

      // 3. Kalkulasi
      if (startDay <= daysInMonth) {
         // --- Hitung MAX HADIR (Target) ---
         const totalDaysPotential = daysInMonth - startDay + 1;

         if (totalDaysPotential > 0) {
             const totalWeeks = totalDaysPotential / 7;
             const estimatedOffs = Math.floor(totalWeeks); 
             allowedOffs = estimatedOffs;
             maxHadir = totalDaysPotential - allowedOffs;
         } else {
             maxHadir = 0;
             allowedOffs = 0;
         }

         // --- Hitung REALISASI LIBUR (Logic Baru) ---
         if (startDay <= effectiveEndDay) {
             const elapsedDays = effectiveEndDay - startDay + 1;

             // PERBAIKAN: Hitung murni selisih hari lewat vs hari masuk
             // Ini mencakup SEMUA hari tidak masuk (Jatah Libur + Absen Lain)
             // Jika karyawan ambil 2 hari libur jatah, maka (Hari Lewat - Hari Masuk) = 2.
             totalLibur = Math.max(0, elapsedDays - totalHadirUnique);
         } else {
             totalLibur = 0;
         }

      } else {
         maxHadir = 0;
         allowedOffs = 0;
         totalLibur = 0;
      }
    }
  }

  const disciplineRate = totalHadirUnique > 0 ? Math.round((totalTepat / totalHadirUnique) * 100) : 0;
  const attendanceProgress = maxHadir > 0 ? Math.min(100, Math.round((totalHadirUnique / maxHadir) * 100)) : 0;

  // Opsi Dropdown Bulan
  const months = Array.from(new Set(attendanceHistory.map(item => {
    const timeStr = (item as any).waktu || (item as any).Waktu || (item as any).timestamp || (item as any).Timestamp;
    const date = parseDateHelper(timeStr);
    if (!date) return "";
    return `${monthFullNames[date.getMonth()]} ${date.getFullYear()}`;
  }))).filter(m => m !== "");

  if (!months.includes(currentMonthYearFilter)) {
    months.unshift(currentMonthYearFilter);
  }

  if (showSuccessView) {
    return (
      <div className="relative z-20 min-h-[60vh] flex flex-col items-center justify-center animate-in fade-in zoom-in duration-500 max-w-lg mx-auto px-4">
           <div className="glass-card p-10 !rounded-[3rem] w-full text-center space-y-8 bg-black/20 border-2 border-emerald-500/30 shadow-[0_0_50px_rgba(52,211,153,0.2)]">
              <div className="w-24 h-24 rounded-full bg-emerald-500/20 flex items-center justify-center mx-auto mb-4 border border-emerald-500/50 shadow-[0_0_30px_rgba(52,211,153,0.3)]">
                <CheckCircleIcon size={50} className="text-emerald-400" />
              </div>
              <div className="space-y-4">
                 <h3 className="text-3xl font-black text-white uppercase tracking-tight leading-none">Absensi<br/>Berhasil!</h3>
                 <p className="text-emerald-glow text-xs font-black tracking-widest uppercase">Data Tersimpan</p>
                 <p className="text-white/60 text-xs font-medium leading-relaxed px-2">
                   Terima kasih atas dedikasi Anda hari ini. Selamat bekerja dan berikan yang terbaik!
                 </p>
              </div>
              <button 
                onClick={() => {
                  setShowSuccessView(false);
                  onAttendanceSuccess(); 
                }}
                className="glass-button w-full !rounded-2xl active-emerald-tab mt-2"
              >
                LANJUT KE MATERI
              </button>
           </div>
      </div>
    );
  }

  return (
    <div className="relative z-20 space-y-8 animate-in fade-in duration-700 max-w-lg mx-auto pb-32 px-4">
      <div className="flex items-center glass-card p-1 !rounded-full h-14 bg-black/40">
        <button onClick={() => setActiveView('absen')} className={`flex-1 h-12 rounded-full text-[10px] font-black uppercase tracking-widest ${activeView === 'absen' ? 'active-emerald-tab' : 'text-white/30'}`}>Absensi</button>
        <button onClick={() => setActiveView('laporan')} className={`flex-1 h-12 rounded-full text-[10px] font-black uppercase tracking-widest ${activeView === 'laporan' ? 'active-emerald-tab' : 'text-white/30'}`}>Riwayat</button>
      </div>

      {activeView === 'absen' ? (
        <div className="space-y-6 flex flex-col items-center">
          <header className="text-center w-full">
            <h2 className="text-3xl font-black tracking-normal text-white">Presensi Digital</h2>
            <p className="text-emerald-glow text-[11px] uppercase font-black mt-2 tracking-[0.4em]">{currentTime.toLocaleTimeString('id-ID')}</p>
          </header>

          <div className="glass-card p-8 !rounded-[2.5rem] space-y-6 bg-black/20 w-full text-left">
            <div className="flex gap-2">
              <button disabled={isCurrentlyCheckedIn} onClick={() => setJenis('Masuk')} className={`flex-1 py-4 rounded-xl text-[10px] font-black uppercase ${jenis === 'Masuk' ? 'active-emerald-tab' : 'bg-white/5 opacity-40'}`}>Masuk {isCurrentlyCheckedIn && "✓"}</button>
              <button disabled={!isCurrentlyCheckedIn} onClick={() => setJenis('Pulang')} className={`flex-1 py-4 rounded-xl text-[10px] font-black uppercase ${jenis === 'Pulang' ? 'active-emerald-tab' : 'bg-white/5 opacity-40'}`}>Pulang</button>
            </div>

            <div className="space-y-5">
              <div className="space-y-2 w-full">
                <label className="text-[10px] opacity-60 uppercase ml-2 font-black text-white tracking-widest">Shift Kerja</label>
                <select value={shift} onChange={(e) => setShift(e.target.value)} disabled={isCurrentlyCheckedIn} className="glass-input !h-14 !rounded-xl text-[11px] font-bold">
                  <option value="">-- Pilih Shift --</option>
                  <option value="Pagi">Pagi (08:30-17:00)</option>
                  <option value="Siang">Siang (12:30-21:00)</option>
                  <option value="Full Day">Full Day (08:30-21:00)</option>
                </select>
              </div>

              <div className="space-y-2 w-full">
                <label className="text-[10px] opacity-60 uppercase ml-2 font-black text-white tracking-widest">Lokasi Cabang</label>
                <select value={cabang} onChange={(e) => setCabang(e.target.value)} className="glass-input !h-14 !rounded-xl text-sm font-bold">
                  <option value="">-- Pilih Lokasi --</option>
                  {lokasiData.map((l: any, i) => {
                    const n = String(l?.namacabang || l?.nama || l?.Nama || "Cabang Flow");
                    return <option key={i} value={n}>{n.toUpperCase()}</option>;
                  })}
                </select>
              </div>
            </div>

            {cabang && distance !== null && (
              <div className="pt-2 flex items-center justify-between px-2">
                <span className="text-[10px] font-black uppercase tracking-widest opacity-40 italic">Status Lokasi:</span>
                <span className={`text-[10px] font-black tracking-widest uppercase ${isInsideRadius ? 'text-emerald-400' : 'text-red-500'}`}>
                  {Math.round(distance)} Meter 
                  {isInsideRadius ? ' (DI AREA)' : ' (LUAR RADIUS)'}
                </span>
              </div>
            )}
          </div>

          <div className="flex flex-col items-center py-4 w-full relative">
            <div className="camera-circle-frame shadow-2xl relative mb-4" onClick={startCamera}>
              {isCameraOpen ? (
                <video ref={videoRef} autoPlay playsInline muted style={{ transform: 'scaleX(-1)' }} />
              ) : photo ? (
                <div className="relative w-full h-full">
                  <img src={photo} alt="Selfie" className="w-full h-full object-cover" />
                  <button onClick={resetPhoto} className="absolute bottom-6 left-1/2 -translate-x-1/2 w-12 h-12 glass-card !rounded-full flex items-center justify-center border border-white/20 active:scale-90 transition-transform bg-red-500/30 z-50 shadow-xl">
                    <svg className="w-6 h-6 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                    </svg>
                  </button>
                </div>
              ) : (
                <div className="text-center opacity-30 flex flex-col items-center">
