import React, { useState, useEffect, useMemo } from 'react';
import { api } from '../services/apiService';
import { User } from '../types';

interface TaskStatus {
  done: boolean;
  locked: boolean;
  time?: string;
  timestamp?: string;
}

// Parser tanggal yang lebih kuat untuk menangani format Google Sheets (M/D/YYYY H:mm:ss atau ISO)
const parseChecklistDate = (dateStr: any): Date | null => {
  try {
    if (!dateStr) return null;
    if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;

    const s = String(dateStr).trim();

    // Coba parse ISO standar dulu
    const isoTry = new Date(s);
    if (!isNaN(isoTry.getTime()) && s.includes('T')) return isoTry;

    // Handle format Sheet: 1/20/2026 2:05:32 atau 18/01/2026
    const datePart = s.split(/[ ,T]+/)[0]; // Ambil bagian tanggal saja
    const bits = datePart.split(/[\/\-\.]/);

    if (bits.length === 3) {
      let d, m, y;
      const b0 = parseInt(bits[0]);
      const b1 = parseInt(bits[1]);
      const b2 = parseInt(bits[2]);

      // Deteksi format berdasarkan posisi tahun (4 digit)
      if (bits[2].length === 4) {
        // Asumsi format Sheet default US (M/D/YYYY) jika b0 <= 12, tapi kita coba deteksi cerdas
        // Jika b0 > 12, pasti DD/MM/YYYY. Jika tidak, prioritas ke MM/DD/YYYY sesuai screenshot sheet user.
        if (b0 > 12) { 
          d = b0; m = b1; y = b2; 
        } else { 
          m = b0; d = b1; y = b2; 
        }
      } else if (bits[0].length === 4) { // YYYY/MM/DD
        y = b0; m = b1; d = b2;
      } else {
        return null;
      }

      const parsedDate = new Date(y, m - 1, d);
      return isNaN(parsedDate.getTime()) ? null : parsedDate;
    }
    return null;
  } catch (e) { return null; }
};

export const Checklist: React.FC<{ user: User, tugasMaster: any[] }> = ({ user, tugasMaster }) => {
  const [activeTab, setActiveTab] = useState<'Harian' | 'Mingguan' | 'Bulanan'>('Harian');
  const [completed, setCompleted] = useState<Record<string, TaskStatus>>({});
  const [isSending, setIsSending] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncTime, setLastSyncTime] = useState<string>('');

  // Logika cek periode waktu
  const isSamePeriod = (timestamp: string, period: string) => {
    const d = parseChecklistDate(timestamp);
    if (!d) return false;
    const now = new Date();

    // Reset jam agar perbandingan murni tanggal
    const dZero = new Date(d); dZero.setHours(0,0,0,0);
    const nowZero = new Date(now); nowZero.setHours(0,0,0,0);

    if (period === 'Harian') {
      return dZero.getTime() === nowZero.getTime();
    }

    if (period === 'Bulanan') {
      return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
    }

    if (period === 'Mingguan') {
       // Hitung nomor minggu (Week Number)
       const getWeek = (date: Date) => {
         const onejan = new Date(date.getFullYear(), 0, 1);
         const millisecsInDay = 86400000;
         return Math.ceil((((date.getTime() - onejan.getTime()) / millisecsInDay) + onejan.getDay() + 1) / 7);
       };
       return getWeek(d) === getWeek(now) && d.getFullYear() === now.getFullYear();
    }
    return false;
  };

  useEffect(() => {
    const syncWithServer = async () => {
      setIsSyncing(true);
      setCompleted({}); // Reset state lokal sebelum load data baru agar tidak ada "ghost" checklist

      try {
        const history = await api.getChecklistHistory(user.email, user.nama);

        // 1. Filter riwayat sesuai Tab Aktif & Periode Waktu
        const relevantHistory = history.filter((row: any) => 
          (row.jenis_checklist || '').toLowerCase() === activeTab.toLowerCase() && 
          isSamePeriod(row.waktu, activeTab)
        );

        // 2. Ambil HANYA 1 data paling baru (Snapshot Terakhir)
        // API mengembalikan sort by newest, jadi ambil index 0.
        // Jika tidak ada data di hari ini, biarkan kosong.
        if (relevantHistory.length > 0) {
          const latestEntry = relevantHistory[0]; 
          try {
            const dataJSON = JSON.parse(latestEntry.data_laporan_json);

            // Format ulang state agar sesuai UI
            const newStatus: Record<string, TaskStatus> = {};
            Object.entries(dataJSON).forEach(([taskName, status]: [string, any]) => {
              // Bersihkan nama task dari spasi berlebih agar match dengan master data
              const cleanTaskName = taskName.trim();
              newStatus[cleanTaskName] = { ...status, locked: true };
            });

            setCompleted(newStatus);

            // Info kapan terakhir update
            const timeObj = parseChecklistDate(latestEntry.waktu);
            if (timeObj) {
              setLastSyncTime(timeObj.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }));
            }

          } catch (e) {
             console.error("Gagal parse JSON dari Sheet:", e);
          }
        } else {
          setLastSyncTime('');
        }
      } catch (err) {
        console.error("Gagal sinkron checklist:", err);
      } finally {
        setIsSyncing(false);
      }
    };

    syncWithServer();
  }, [activeTab, user.email, user.nama]);

  // Filter tugas master berdasarkan jabatan user & tab aktif
  const tasksToShow = useMemo(() => 
    (tugasMaster || []).filter(t => 
      (t.jabatan || t.Jabatan || '').toLowerCase() === user.jabatan.toLowerCase() && 
      (t.jenis || t.Jenis || '').toLowerCase() === activeTab.toLowerCase()
    ), [tugasMaster, user.jabatan, activeTab]
  );

  const toggleTask = (taskName: string) => {
    // Jangan izinkan ubah jika status locked (sudah terkirim)
    if (completed[taskName]?.locked) return;

    setCompleted(prev => {
      const isDone = prev[taskName]?.done || false;
      const now = new Date();
      const timeStr = `${now.getHours()}:${now.getMinutes().toString().padStart(2,'0')}`;

      if (isDone) {
        // Jika uncheck, hapus dari state
        const newState = { ...prev };
        delete newState[taskName];
        return newState;
      } else {
        // Jika check
        return { 
          ...prev, 
          [taskName]: { 
            done: true, 
            locked: false, 
            time: timeStr, 
            timestamp: now.toISOString() 
          } 
        };
      }
    });
  };

  const handleSubmit = async () => {
    // Gabungkan data existing (locked) + data baru
    const allChecked: Record<string, TaskStatus> = {};
    const newItemsCount = Object.values(completed).filter((s: TaskStatus) => s.done && !s.locked).length;

    if (newItemsCount === 0) return alert("Tidak ada tugas baru untuk dikirim.");

    // Kirim SEMUA yang sedang tercentang (Snapshot state saat ini)
    Object.entries(completed).forEach(([name, s]) => {
      const status = s as TaskStatus;
      if (status.done) {
        allChecked[name] = status;
      }
    });

    setIsSending(true);
    try {
      const res = await api.kirimTugas({
        nama: user.nama, email: user.email, jabatan: user.jabatan, jenis: activeTab,
        totalTugas: tasksToShow.length, totalSelesai: Object.keys(allChecked).length,
        checklist: allChecked
      });

      if (res.status === 'sukses') {
        // Kunci semua task setelah sukses kirim
        const updated = { ...completed };
        Object.keys(updated).forEach(name => { updated[name].locked = true; });
        setCompleted(updated);

        const now = new Date();
        setLastSyncTime(now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }));
        alert("Laporan berhasil disimpan!");
      } else {
        alert("Gagal mengirim ke server.");
      }
    } catch (e) {
      alert("Masalah koneksi internet.");
    } finally { setIsSending(false); }
  };

  const totalSelesai = Object.values(completed).filter((s: TaskStatus) => s.done).length;
  const totalTugas = tasksToShow.length;
  const progressPercent = totalTugas > 0 ? Math.round((totalSelesai / totalTugas) * 100) : 0;
  const hasNew = Object.values(completed).some((s: TaskStatus) => s.done && !s.locked);

  return (
    <div className="space-y-10 animate-in slide-in-from-right-4 duration-500 w-full max-w-md mx-auto pb-32 px-2 text-left">
      <header className="px-2">
        <h2 className="text-3xl font-black text-white">Checklist Tugas</h2>
        <div className="flex items-center gap-2 mt-2">
          <p className="text-emerald-glow text-[10px] font-black uppercase tracking-[0.4em] italic">
            {user.jabatan} • {activeTab}
          </p>
          {lastSyncTime && (
             <span className="text-[8px] text-white/30 font-bold uppercase tracking-widest border-l border-white/20 pl-2">
               Updated {lastSyncTime}
             </span>
          )}
        </div>
      </header>

      {/* Kartu Statistik */}
      <div className="glass-card p-6 !rounded-[2.5rem] bg-black/30 border border-white/5 space-y-6 shadow-2xl overflow-hidden px-8 relative z-10">
        <div className="flex items-center gap-6">
          <div className="relative w-24 h-24 shrink-0 flex items-center justify-center">
             <svg viewBox="0 0 100 100" className="w-full h-full transform -rotate-90">
                <circle cx="50" cy="50" r="42" stroke="rgba(255,255,255,0.05)" strokeWidth="10" fill="transparent" />
                <circle 
                  cx="50" cy="50" r="42" stroke="#34d399" strokeWidth="10" fill="transparent" 
                  strokeDasharray="263.8" strokeDashoffset={263.8 * (1 - progressPercent/100)} 
                  strokeLinecap="round" className="transition-all duration-1000 ease-out"
                />
             </svg>
             <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-lg font-black text-white italic tracking-tighter">{progressPercent}%</span>
             </div>
          </div>
          <div className="flex-1 space-y-2">
             <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.2em] italic leading-tight">Progres {activeTab}</p>
             <p className="text-sm font-bold text-white/90 leading-tight">{totalSelesai} dari {totalTugas} tugas selesai.</p>
             <div className="pt-2">
               <span className={`text-[8px] font-black px-3 py-1 rounded-full uppercase tracking-widest ${isSyncing ? 'bg-emerald-400/20 text-emerald-glow animate-pulse' : 'bg-white/5 text-white/30'}`}>
                 {isSyncing ? "SYNCING..." : "LIVE DATA"}
               </span>
             </div>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex items-center glass-card p-1 !rounded-full h-14 bg-black/40">
        {(['Harian', 'Mingguan', 'Bulanan'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 h-12 rounded-full text-[9px] font-black transition-all uppercase tracking-widest ${activeTab === tab ? 'active-emerald-tab' : 'text-white/30'}`}>{tab}</button>
        ))}
      </div>

      {/* Daftar Tugas */}
      <div className="space-y-4 px-2">
        <div className="space-y-3">
          {tasksToShow.length > 0 ? tasksToShow.map((t: any, i: number) => {
            const name = (t.tugas || t.Tugas || '').trim(); // Pastikan nama bersih dari spasi
            const status = completed[name] || { done: false, locked: false };
            return (
              <button key={i} disabled={status.locked || isSyncing} onClick={() => toggleTask(name)} className={`w-full glass-card p-6 !rounded-[2rem] flex items-center justify-between text-left transition-all ${status.locked ? 'opacity-50 bg-white/5 cursor-default' : 'bg-black/20 active:scale-[0.98]'}`}>
                <div className="flex items-center gap-5 overflow-hidden w-full">
                  <div className={`w-8 h-8 rounded-full border-2 shrink-0 flex items-center justify-center transition-all ${status.done ? 'bg-emerald-400 border-emerald-400 shadow-[0_0_15px_rgba(52,211,153,0.3)]' : 'border-white/10'}`}>
                    {status.done && <span className="text-black font-black text-xs">✓</span>}
                  </div>
                  <div className="flex flex-col gap-0.5 min-w-0 flex-1">
                    <p className={`font-bold text-sm tracking-tight leading-snug break-words whitespace-normal ${status.done ? 'text-white/40 line-through' : 'text-white'}`}>{name}</p>
                    <div className="flex items-center justify-between">
                      {status.done && status.time && <p className="text-[9px] font-black text-white/30 tracking-widest">{status.time}</p>}
                      {status.locked && <p className="text-[8px] font-black text-emerald-glow uppercase tracking-widest italic">Tersimpan</p>}
                    </div>
                  </div>
                </div>
              </button>
            );
          }) : (
            <div className="py-20 text-center opacity-30 text-[10px] font-black uppercase tracking-widest">
              {isSyncing ? "MEMUAT DATA..." : "TIDAK ADA TUGAS"}
            </div>
          )}
        </div>
      </div>

      {hasNew && (
        <div className="fixed bottom-6 left-0 right-0 px-6 z-50 animate-in slide-in-from-bottom-4">
          <button onClick={handleSubmit} disabled={isSending} className="glass-button h-16 w-full max-w-md mx-auto !rounded-2xl active-emerald-tab uppercase shadow-2xl">
            {isSending ? "MENGIRIM..." : "SIMPAN PROGRES"}
          </button>
        </div>
      )}
    </div>
  );
};

