                  <div className="text-right pt-2 relative z-20">
                    <button 
                      type="button" 
                      onClick={handleForgotPassword} 
                      disabled={isResetting}
                      className="text-[10px] font-bold text-white/40 uppercase tracking-widest hover:text-white transition-colors disabled:opacity-30 cursor-pointer p-1"
                    >
                      {isResetting ? "MENGIRIM..." : "LUPA PASSWORD?"}
