                    <span className="text-[9px] font-black text-emerald-glow tracking-[0.3em] uppercase">Kontak Darurat</span>
                    <div className="h-[1px] flex-1 bg-white/10"></div>
                  </div>
                  <div className="space-y-5">
                    <InputGroup label="Nama Kontak" value={kNama} onChange={(e: any) => setKNama(e.target.value)} placeholder="Contoh: Siti Aminah" />
                    <InputGroup label="Hubungan" value={kHub} onChange={(e: any) => setKHub(e.target.value)} placeholder="Contoh: Ibu Kandung" />
                    <InputGroup label="No. WA Darurat" type="tel" value={kWa} onChange={(e: any) => setKWa(e.target.value)} placeholder="0812xxxxxxxx" />
