        <button onClick={() => { setIsSignup(!isSignup); window.scrollTo(0,0); }} className="text-[10px] font-black text-white/40 uppercase tracking-[0.4em] pt-4">
          {isSignup ? "Sudah terdaftar? Silakan Login" : "Belum punya akses? Daftar Akun"}
        </button>
      </div>
    </div>
  );
};

